function subscribe(target, event, listener) {
  target.addEventListener(event, listener);
  return function () {
    target.removeEventListener(event, listener);
  };
}

var fired = 0;
var box = { handlers: {},
  addEventListener: function (name, fn) { this.handlers[name] = fn; },
  removeEventListener: function (name) { delete this.handlers[name]; } };

var unsubscribe = subscribe(box, "tick", function () { fired++; });
console.log(typeof unsubscribe);

